import "server-only";
import data from "@/data/catalog.json";
import type { Card } from "./format";

/** Generated by scripts/catalog.py from the old ps.me shop. Server-only: the JSON is ~360 KB. */
export type Product = {
  id: number;
  slug: string;
  name: string;
  price: number;
  section: string;
  sub: string | null;
  brand: string | null;
  vol: string | null;
  img: boolean;
  cut: boolean;
  ar: number;
  popular: boolean;
  desc: [string, string][];
};
export type Sub = { id: string; name: string; count: number };
export type Section = { id: string; old: string; name: string; lead: string; count: number; subs: Sub[] };
export type Brand = { id: string; name: string; count: number };

export const products = data.products as Product[];
export const sections = data.sections as Section[];
export const brands = data.brands as Brand[];

const bySlug = new Map(products.map((p) => [p.slug, p]));
const byId = new Map(products.map((p) => [p.id, p]));
const brandName = new Map(brands.map((b) => [b.id, b.name]));

export const getProduct = (slug: string) => bySlug.get(slug);
export const getById = (id: number) => byId.get(id);
export const getSection = (id: string) => sections.find((s) => s.id === id);
export const getBrand = (id: string) => brands.find((b) => b.id === id);
export const subName = (sec: string, sub: string | null) => (sub ? getSection(sec)?.subs.find((s) => s.id === sub)?.name : undefined);

export function toCard(p: Product): Card {
  return {
    id: p.id,
    s: p.slug,
    n: p.name,
    p: p.price,
    b: p.brand,
    bn: p.brand ? (brandName.get(p.brand) ?? null) : null,
    sec: p.section,
    sub: p.sub,
    v: p.vol,
    img: p.img,
    cut: p.cut,
    ...(p.popular ? { hot: true } : {}),
  };
}

/** Cards by id, in the given order; unknown ids are skipped. */
export const cards = (ids: number[]) => ids.map((id) => byId.get(id)).filter((p): p is Product => Boolean(p)).map(toCard);

/** Same sub-category first, then same brand, then same section. */
export function related(p: Product, n = 8) {
  const score = (q: Product) => (q.sub && q.sub === p.sub ? 3 : 0) + (q.brand && q.brand === p.brand ? 2 : 0) + (q.section === p.section ? 1 : 0) + (q.img ? 0.5 : 0);
  return products
    .filter((q) => q.id !== p.id && q.section === p.section)
    .map((q) => ({ q, s: score(q) - Math.abs(Math.log((q.price || 1) / (p.price || 1))) * 0.2 }))
    .sort((a, b) => b.s - a.s)
    .slice(0, n)
    .map((x) => toCard(x.q));
}

